displayContent.text:
map $http_upgrade $connection_upgrade {
    default Upgrade;
    '' close;
}
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    location / {
        return 301 https://$host$request_uri;
    }
    location /.well-known/acme-challenge/ {
        root $acme_root;
        default_type "text/plain";
    }
}
server {
    listen 443 ssl default_server;
    listen [::]:443 ssl default_server;
    ssl_certificate /etc/nginx/ssl/_.kortexa.ai_2048/fullchain.cer;
    ssl_certificate_key /etc/nginx/ssl/_.kortexa.ai_2048/private.key;
    server_name _;
    return 404;
}

