    by_kind = {}
    for r in results:
        by_kind[r["kind"]] = by_kind.get(r["kind"], 0) + 1
    print(f"projects: {len(results)}")
    print("by_kind:", json.dumps(by_kind))
    with_ep = sum(1 for r in results if r["endpoints"])
    with_ng = sum(1 for r in results if r["nginx"])
    with_model = sum(1 for r in results if r["model_refs"])
    print(f"with_endpoints: {with_ep}  with_nginx: {with_ng}  with_model_refs: {with_model}")

if __name__ == "__main__":
    main()

