#!/usr/bin/env python3
"""Resolve extracted per-project signals into a nodes+edges graph.
Reads /tmp/src-survey/projects.json, writes /tmp/src-survey/graph.json.
Edge types (priority high->low): api > model > web > ref > served.
Parallel (src,dst) edges are merged, keeping the highest-priority type.
"""
import json, re, pathlib
from collections import Counter

OUT = pathlib.Path("/tmp/src-survey")
data = json.load(open(OUT / "projects.json"))

# --- node filter: drop hidden dirs + truly empty dirs ---
def keep(r):
    if r["name"].startswith("."):
        return False
    if r["files"] == 0 and not r["git"] and not r["description"] and not r["nginx"]:
        return False
    return True

data = [r for r in data if keep(r)]
project_names = {r["name"] for r in data}

# domain -> owning project (from each project's nginx server_name)
domain_map = {}
for r in data:
    if r["nginx"]:
        for dom in r["nginx"]["domains"]:
            domain_map.setdefault(dom.lower(), r["name"])
domain_map["auth.kortexa.ai"] = "api.server"
domain_map["dev.kortexa.ai"] = "api.server"
domain_map["api.kortexa.ai"] = "api.server"

# service port -> project (from api.server/SERVICES_MAPPING.md)
port_map = {
    "4000": "api.server", "4001": "vision.server", "4002": "asr.server",
    "4003": "tts.server", "4004": "image-gen.server", "4005": "video-gen.server",
    "4006": "avery.server", "4007": "penumbra.server", "4008": "shardling.ai",
    "7880": "livekit.server", "8050": "comfyui.server",
}

# distinctive sibling names = contain '.' or '-' (safe from common-word collisions)
distinctive = {n for n in project_names if ("." in n) or ("-" in n)}

def resolve_endpoint(e):
    host = re.sub(r"^https?://", "", e).split("/")[0].split("?")[0]
    m = re.match(r"^(.*?)(?::(\d+))?$", host)
    h = m.group(1).lower()
    p = m.group(2)
    if p and p in port_map:
        return port_map[p], "api"
    if "kortexa" in h:
        if h in domain_map:
            t = domain_map[h]
            return t, ("api" if t == "api.server" else "web")
        mm = re.match(r"^([a-z0-9-]+)\.kortexa\.(?:ai|com)$", h)
        if mm:
            sub = mm.group(1)
            if sub in project_names and sub != "kortexa":
                return sub, "web"
    return None

PRIORITY = {"api": 4, "model": 3, "web": 2, "ref": 1, "served": 0}
raw = {}  # (src,dst) -> {"types":set, "weight":int}

def add_edge(src, dst, etype, w=1):
    if src == dst or dst not in project_names:
        return
    key = (src, dst)
    e = raw.setdefault(key, {"types": set(), "weight": 0})
    e["types"].add(etype)
    e["weight"] += w

for r in data:
    src = r["name"]
    for e in r["endpoints"]:
        res = resolve_endpoint(e)
        if res:
            add_edge(src, res[0], res[1])
    if r["model_refs"]:
        add_edge(src, "models.server", "model", len(r["model_refs"]))
    for nm, cnt in r["mentions"].items():
        if nm in distinctive:
            add_edge(src, nm, "ref", cnt)
    if r["nginx"]:
        add_edge(src, "nginx", "served")

nodes = []
for r in data:
    nodes.append({
        "id": r["name"], "name": r["name"], "kind": r["kind"], "type": r["type"],
        "title": r["title"], "description": r["description"],
        "domains": (r["nginx"]["domains"] if r["nginx"] else []),
        "ext_dep_count": r["ext_dep_count"], "files": r["files_scanned"],
    })
nodes.append({"id": "nginx", "name": "nginx", "kind": "infra", "type": [],
              "title": "nginx edge proxy",
              "description": "Reverse proxy / TLS termination for web-deployed projects",
              "domains": [], "ext_dep_count": 0, "files": 0})

edge_list = []
for (s, d), e in raw.items():
    etype = max(e["types"], key=lambda t: PRIORITY[t])
    edge_list.append({"source": s, "target": d, "type": etype,
                      "types": sorted(e["types"], key=lambda t: -PRIORITY[t]),
                      "weight": e["weight"]})

graph = {
    "nodes": nodes, "edges": edge_list,
    "meta": {
        "generated": "2026-08-18", "projects": len(data),
        "edge_types": {
            "api": "calls a backend service (service port or api.kortexa.ai)",
            "model": "consumes model weights from models.server",
            "web": "references another project's deployed web domain",
            "ref": "references a sibling project by name (code/config)",
            "served": "served behind nginx",
        },
    },
}
(OUT / "graph.json").write_text(json.dumps(graph, indent=2))

ec = Counter(e["type"] for e in edge_list)
outdeg = Counter(e["source"] for e in edge_list)
indeg = Counter(e["target"] for e in edge_list)
allids = {n["id"] for n in nodes}
isolated = [n["id"] for n in nodes
            if n["id"] not in set(outdeg) and n["id"] not in set(indeg)]
print(f"nodes: {len(nodes)}  edges: {len(edge_list)}")
print("edge types:", dict(ec))
print("top sources (out):", outdeg.most_common(12))
print("top targets (in):", indeg.most_common(12))
print(f"isolated ({len(isolated)}):", isolated)

