Force sim:
```js
let alpha = 1;
const REP = 2600;      // repulsion strength
const SPRING = 0.02;   // spring stiffness
const REST = 90;       // rest length
const GRAV = 0.015;    // centering
const DAMP = 0.85;
function tick(){
  // repulsion O(n^2)
  for(let i=0;i<nodes.length;i++){
    const a = nodes[i];
    for(let j=i+1;j<nodes.length;j++){
      const b = nodes[j];
      let dx=a.x-b.x, dy=a.y-b.y;
      let d2=dx*dx+dy*dy; if(d2<1)d2=1;
      const d=Math.sqrt(d2);
      const f=REP/d2;
      const fx=dx/d*f, fy=dy/d*f;
      a.vx+=fx; a.vy+=fy; b.vx-=fx; b.vy-=fy;
    }
  }
  // springs
  for(const e of edges){
    const a=byId[e.source], b=byId[e.target];
    let dx=b.x-a.x, dy=b.y-a.y;
    let d=Math.sqrt(dx*dx+dy*dy)||1;
    const f=(d-REST)*SPRING;
    const fx=dx/d*f, fy=dy/d*f;
    a.vx+=fx; a.vy+=fy; b.vx-=fx; b.vy-=fy;
  }
  // gravity + integrate
  for(const n of nodes){
    n.vx -= n.x*GRAV; n.vy -= n.y*GRAV;
    if(n.fixed){ n.vx=0; n.vy=0; continue; }
    n.vx*=DAMP; n.vy*=DAMP;
    n.x+=n.vx*alpha; n.y+=n.vy*alpha;
  }
  alpha *= 0.995;
  if(alpha<0.02) alpha=0.02; // keep a floor for gentle motion? or stop
}
```

